import json, sys

def text_of(content):
    out=[]
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        for b in content:
            if not isinstance(b, dict):
                out.append(str(b)); continue
            t=b.get('type')
            if t=='text':
                out.append(b.get('text',''))
            elif t=='thinking':
                out.append('[THINKING] '+b.get('thinking',''))
            elif t=='tool_use':
                name=b.get('name','')
                inp=b.get('input',{})
                # show command/file_path/description and small inputs
                short={}
                for k in ('command','file_path','description','pattern','path','content','old_string','new_string','prompt','query'):
                    if k in inp:
                        v=inp[k]
                        if isinstance(v,str) and len(v)>4000: v=v[:4000]+'...[trunc]'
                        short[k]=v
                out.append(f'[TOOL_USE {name}] '+json.dumps(short))
            elif t=='tool_result':
                c=b.get('content','')
                out.append('[TOOL_RESULT] '+text_of(c))
            else:
                out.append(json.dumps(b)[:2000])
    return '\n'.join(out)

path=sys.argv[1]
with open(path) as fh:
    for i,line in enumerate(fh):
        line=line.strip()
        if not line: continue
        try:
            obj=json.loads(line)
        except Exception:
            continue
        msg=obj.get('message')
        if not isinstance(msg, dict):
            continue
        role=msg.get('role', obj.get('type',''))
        content=msg.get('content','')
        txt=text_of(content)
        if not txt.strip(): continue
        ts=obj.get('timestamp','')
        print(f'\n===== [{i}] role={role} ts={ts} =====')
        print(txt)
PYEOF
